import{_ as t,o as s,c as n,ai as o}from"./chunks/framework.C33Uq6m-.js";const r="/llmxray/docs/educators/fr/context-window.svg",a="/llmxray/docs/educators/fr/token-budget.svg",i="/llmxray/docs/educators/fr/memory-strategies.svg",v=JSON.parse('{"title":"Module 5 : Quand le modèle oublie-t-il ?","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/educators/module-5.md","filePath":"fr/community/educators/module-5.md"}'),l={name:"fr/community/educators/module-5.md"};function u(d,e,c,m,p,g){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="module-5-quand-le-modele-oublie-t-il" tabindex="-1">Module 5 : Quand le modèle oublie-t-il ? <a class="header-anchor" href="#module-5-quand-le-modele-oublie-t-il" aria-label="Permalink to &quot;Module 5 : Quand le modèle oublie-t-il ?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>L&#39;Archéologue</strong> — Explorez les frontières de la mémoire</p><p><strong>Durée :</strong> 60 min | <strong>Difficulté :</strong> Intermédiaire | <strong>Prérequis :</strong> <a href="./module-1.html">Module 1</a>, <a href="./module-4.html">Module 4</a></p></div><h2 id="le-moment-eureka" tabindex="-1">Le Moment Eureka <a class="header-anchor" href="#le-moment-eureka" aria-label="Permalink to &quot;Le Moment Eureka&quot;">​</a></h2><blockquote><p>Le contexte n&#39;est pas de la mémoire — c&#39;est une fenêtre glissante. Le modèle ne se souvient pas de votre conversation. Il relit l&#39;intégralité de la transcription à chaque fois, et lorsqu&#39;il n&#39;a plus de place, les anciens messages disparaissent tout simplement.</p></blockquote><p>C&#39;est l&#39;intuition qui déconstruit l&#39;illusion la plus répandue au sujet des assistants IA : qu&#39;ils &quot;se souviennent&quot; de vous. Quand vous discutez avec un modèle de langage, cela ressemble à une conversation continue avec un être qui se rappelle ce que vous avez dit il y a cinq minutes. En réalité, chaque appel API envoie <strong>l&#39;intégralité de l&#39;historique de conversation</strong> depuis le début. Le modèle ne possède aucun état interne persistant entre les appels — pas de registre mémoire, pas de journal, pas de classeur. Il reçoit un bloc de texte, génère une réponse, et oublie immédiatement tout.</p><p>Les conséquences sont profondes. Il existe une limite stricte — la <strong>fenêtre de contexte</strong> (context window) — sur la quantité de texte que peut contenir ce bloc. Lorsque votre conversation la dépasse, les messages les plus anciens sont silencieusement supprimés. Le modèle ne résume pas gracieusement ce qu&#39;il a perdu. Il ne signale pas qu&#39;il ne peut plus voir vos instructions antérieures. Ces messages cessent simplement d&#39;exister du point de vue du modèle, comme s&#39;ils n&#39;avaient jamais été écrits. Comprendre cela transforme la façon dont les étudiants conçoivent leurs prompts, structurent leurs conversations et évaluent la fiabilité des systèmes IA en production.</p><hr><h2 id="contexte-conceptuel" tabindex="-1">Contexte Conceptuel <a class="header-anchor" href="#contexte-conceptuel" aria-label="Permalink to &quot;Contexte Conceptuel&quot;">​</a></h2><h3 id="qu-est-ce-qu-une-fenetre-de-contexte" tabindex="-1">Qu&#39;est-ce qu&#39;une fenêtre de contexte ? <a class="header-anchor" href="#qu-est-ce-qu-une-fenetre-de-contexte" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;une fenêtre de contexte ?&quot;">​</a></h3><p>Une <strong>fenêtre de contexte</strong> (context window) est le tampon de taille fixe en tokens qu&#39;un modèle de langage peut traiter en un seul appel. Ce n&#39;est pas de la mémoire. Ce n&#39;est pas du stockage. C&#39;est plutôt comme un bureau — on ne peut y étaler qu&#39;une quantité limitée de papier avant que des feuilles ne commencent à tomber du bord.</p><p>Chaque fois que vous envoyez un message, l&#39;application assemble un bloc de texte unique contenant :</p><ul><li>Le prompt système (instructions sur le comportement du modèle)</li><li>L&#39;historique complet de la conversation (tous les messages précédents de l&#39;utilisateur et les réponses de l&#39;assistant)</li><li>Votre dernier message</li></ul><p>Ce bloc entier est envoyé au modèle comme une seule entrée. Le modèle le lit en intégralité, génère une réponse, puis <strong>ne retient rien</strong>. La prochaine fois que vous envoyez un message, l&#39;application reconstruit le bloc depuis le début, incluant désormais la réponse précédente du modèle dans l&#39;historique.</p><p>La fenêtre de contexte définit la taille maximale de ce bloc, mesurée en tokens. Si le bloc assemblé dépasse la limite, quelque chose doit être coupé.</p><p><img src="'+r+'" alt="La fenêtre de contexte"></p><h3 id="budget-de-tokens-qui-obtient-quoi" tabindex="-1">Budget de tokens : qui obtient quoi ? <a class="header-anchor" href="#budget-de-tokens-qui-obtient-quoi" aria-label="Permalink to &quot;Budget de tokens : qui obtient quoi ?&quot;">​</a></h3><p>La fenêtre de contexte est un <strong>budget partagé</strong>. Chaque composant de l&#39;entrée est en concurrence pour le même pool de tokens :</p><table tabindex="0"><thead><tr><th>Composant</th><th>Coût typique en tokens</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Prompt système</strong></td><td>50 - 500 tokens</td><td>Instructions, personnalité, règles</td></tr><tr><td><strong>Historique de conversation</strong></td><td>Croît à chaque tour</td><td>Chaque tour utilisateur + assistant ajoute des tokens</td></tr><tr><td><strong>Dernier message de l&#39;utilisateur</strong></td><td>10 - 500 tokens</td><td>La requête en cours</td></tr><tr><td><strong>Réservé pour la réponse</strong></td><td>Dépend du modèle</td><td>Le modèle a besoin d&#39;espace pour générer sa sortie</td></tr></tbody></table><p>Considérons un modèle avec une fenêtre de contexte de 4 096 tokens. Si votre prompt système consomme 200 tokens et que vous réservez 500 tokens pour la réponse du modèle, il vous reste environ 3 396 tokens pour l&#39;historique de conversation. Si chaque tour (message utilisateur + réponse de l&#39;assistant) consomme en moyenne 300 tokens, vous pouvez loger environ <strong>11 tours</strong> avant que la fenêtre ne soit pleine.</p><p>Avec une fenêtre de 2 048 tokens, cette même configuration ne laisse de place que pour environ <strong>4-5 tours</strong>. La conversation se remplit remarquablement vite.</p><p>C&#39;est pourquoi la longueur du prompt système est importante. Un prompt système verbeux qui consomme 800 tokens vole de l&#39;espace directement à votre historique de conversation. Chaque token dépensé pour les instructions est un token indisponible pour le contexte.</p><p><img src="'+a+'" alt="Répartition du budget de tokens"></p><div class="warning custom-block"><p class="custom-block-title">Les prompts système sont invisibles mais coûteux</p><p>De nombreuses applications IA injectent de longs prompts système que les utilisateurs ne voient jamais — définitions de personnalité, consignes de sécurité, règles de formatage de la sortie. Ceux-ci peuvent consommer des centaines, voire des milliers de tokens avant que l&#39;utilisateur ne tape un seul mot. Lorsqu&#39;un modèle semble &quot;oublier&quot; des parties antérieures de votre conversation, le prompt système caché peut en être partiellement responsable.</p></div><h3 id="que-se-passe-t-il-lorsque-le-contexte-deborde" tabindex="-1">Que se passe-t-il lorsque le contexte déborde ? <a class="header-anchor" href="#que-se-passe-t-il-lorsque-le-contexte-deborde" aria-label="Permalink to &quot;Que se passe-t-il lorsque le contexte déborde ?&quot;">​</a></h3><p>Lorsque l&#39;entrée assemblée dépasse la fenêtre de contexte, l&#39;application doit la tronquer. La stratégie la plus courante est une <strong>fenêtre glissante</strong> (sliding window) : les messages les plus anciens de l&#39;historique sont supprimés jusqu&#39;à ce que l&#39;entrée rentre dans la limite.</p><p>Ce n&#39;est pas une dégradation gracieuse. Il n&#39;y a pas de &quot;mémoire floue&quot; des messages plus anciens, pas de rappel partiel, pas de système de priorité qui conserve les éléments importants. C&#39;est une coupure nette :</p><ul><li><strong>Avant la troncature</strong> : Le modèle peut voir les messages 1 à 20</li><li><strong>Après la troncature</strong> : Le modèle peut voir les messages 8 à 20. Les messages 1 à 7 ont disparu.</li></ul><p>Le modèle n&#39;a aucune conscience que quelque chose a été supprimé. Il ne peut pas vous dire &quot;Je connaissais votre nom mais je l&#39;ai oublié&quot;. De son point de vue, la conversation commence simplement au message 8. Si vous lui avez communiqué votre nom au message 1 et que vous le demandez au message 21, il avouera son ignorance ou — pire — hallucinerait un nom.</p><p>Cela crée une catégorie de bugs subtils dans les applications IA :</p><ul><li>Les instructions données en début de conversation expirent silencieusement</li><li>Le modèle contredit ses propres déclarations antérieures parce qu&#39;il ne peut plus les voir</li><li>Les utilisateurs perçoivent le modèle comme &quot;amnésique&quot; ou &quot;incohérent&quot; sans comprendre pourquoi</li></ul><h3 id="strategies-de-memoire-lutter-contre-l-oubli" tabindex="-1">Stratégies de mémoire : lutter contre l&#39;oubli <a class="header-anchor" href="#strategies-de-memoire-lutter-contre-l-oubli" aria-label="Permalink to &quot;Stratégies de mémoire : lutter contre l&#39;oubli&quot;">​</a></h3><p>La fenêtre de contexte étant fondamentalement limitée, les applications utilisent diverses stratégies pour préserver les informations importantes au fil de conversations plus longues. LLMxRay implémente une <strong>approche à quatre niveaux</strong>, chacun avec des compromis différents :</p><p><strong>1. Fenêtre glissante (sliding window, par défaut)</strong> La stratégie la plus simple : conserver les N messages les plus récents et supprimer tout ce qui est plus ancien. Rapide et prévisible, mais le contexte ancien disparaît complètement. Vous pouvez configurer la taille de la fenêtre (par ex. 20 messages) dans les Chat Settings.</p><p><strong>2. Résumé automatique (Auto-Summarization)</strong> Lorsque la conversation s&#39;allonge, l&#39;application demande au modèle de résumer les messages anciens en un paragraphe condensé. Ce résumé remplace les messages originaux, préservant l&#39;essentiel tout en utilisant bien moins de tokens. Le compromis : les résumés perdent les nuances, les citations exactes et les détails spécifiques.</p><p><strong>3. Faits utilisateur (User Facts)</strong> L&#39;application extrait et stocke les faits clés de la conversation (noms, préférences, objectifs déclarés) dans un format structuré en dehors de la fenêtre de contexte. Ces faits sont injectés dans chaque nouveau prompt sous forme d&#39;une section &quot;mémoire&quot; compacte. Cela préserve les informations critiques, mais ne capture que ce que la logique d&#39;extraction identifie comme important.</p><p><strong>4. Mémoire de messages RAG (RAG Message Memory)</strong> Les messages passés sont convertis en vecteurs (embeddings) et stockés dans IndexedDB. Quand l&#39;utilisateur envoie un nouveau message, l&#39;application recherche les messages passés sémantiquement similaires et injecte les plus pertinents dans le contexte. C&#39;est la stratégie la plus sophistiquée — elle peut retrouver des informations datant de centaines de tours — mais elle dépend de la qualité des embeddings et de la pertinence de la correspondance.</p><p><img src="'+i+'" alt="Stratégies de mémoire"></p><div class="warning custom-block"><p class="custom-block-title">Aucune stratégie n&#39;est parfaite</p><p>Chaque stratégie de mémoire est une compression avec perte de la conversation originale. La fenêtre glissante perd tout ce qui se trouve au-delà de la fenêtre. Le résumé perd les détails. Les faits utilisateur perdent le contexte. La récupération RAG peut manquer des messages pertinents ou en ramener d&#39;inutiles. La contrainte fondamentale — une fenêtre de contexte finie — ne peut pas être entièrement surmontée, seulement atténuée.</p></div><h3 id="longueur-de-contexte-selon-les-modeles" tabindex="-1">Longueur de contexte selon les modèles <a class="header-anchor" href="#longueur-de-contexte-selon-les-modeles" aria-label="Permalink to &quot;Longueur de contexte selon les modèles&quot;">​</a></h3><p>Les modèles varient énormément quant à la taille de leur fenêtre de contexte :</p><table tabindex="0"><thead><tr><th>Modèle</th><th>Fenêtre de contexte</th><th>Pages de texte approximatives</th></tr></thead><tbody><tr><td>Modèles anciens (ère GPT-2)</td><td>1 024 tokens</td><td>~1,5 pages</td></tr><tr><td>LLaMA 2 (7B)</td><td>4 096 tokens</td><td>~6 pages</td></tr><tr><td>LLaMA 3 (8B)</td><td>8 192 tokens</td><td>~12 pages</td></tr><tr><td>Mistral 7B</td><td>32 768 tokens</td><td>~50 pages</td></tr><tr><td>GPT-4 Turbo</td><td>128 000 tokens</td><td>~200 pages</td></tr><tr><td>Claude, Gemini (dernières versions)</td><td>200 000+ tokens</td><td>~300+ pages</td></tr></tbody></table><p>Une réaction naturelle : &quot;Il suffit d&#39;agrandir la fenêtre de contexte.&quot; Mais plus grand n&#39;est pas toujours mieux :</p><ul><li><strong>Le coût de calcul croît quadratiquement</strong> avec la longueur du contexte dans l&#39;attention standard (O(n^2)). Doubler le contexte quadruple le calcul pour la self-attention. Les variantes d&#39;attention efficace (FlashAttention, grouped-query attention) atténuent ce problème mais ne l&#39;éliminent pas.</li><li><strong>La latence augmente</strong> car le modèle doit traiter davantage de tokens avant de générer son premier token de sortie (TTFT plus élevé).</li><li><strong>Le problème du &quot;perdu au milieu&quot;</strong> : Liu et al. (2023) ont démontré que les modèles sont significativement moins performants pour exploiter les informations placées au milieu de longs contextes par rapport aux informations situées au début ou à la fin. Disposer d&#39;une grande fenêtre de contexte ne garantit pas que le modèle exploitera efficacement tout ce qu&#39;elle contient.</li><li><strong>Les modèles locaux sont contraints par la VRAM</strong>. Faire tourner un contexte de 128K sur un GPU grand public n&#39;est pas toujours réalisable. LLMxRay permet de configurer la fenêtre de contexte dans les Chat Settings précisément parce que le matériel local impose des limites réelles.</li></ul><hr><h2 id="exercices-pratiques" tabindex="-1">Exercices Pratiques <a class="header-anchor" href="#exercices-pratiques" aria-label="Permalink to &quot;Exercices Pratiques&quot;">​</a></h2><h3 id="exercice-1-remplir-le-seau" tabindex="-1">Exercice 1 : Remplir le seau <a class="header-anchor" href="#exercice-1-remplir-le-seau" aria-label="Permalink to &quot;Exercice 1 : Remplir le seau&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Ouvrez <strong>Chat Diagnostics</strong> dans LLMxRay</li><li>Allez dans <strong>Chat Settings</strong> et réglez la fenêtre de contexte à <strong>2 048 tokens</strong></li><li>Démarrez une conversation — posez au modèle une série de questions sur différents sujets</li><li>Après chaque message, consultez le <strong>Metrics Dashboard</strong> : observez le nombre de <strong>prompt tokens</strong> qui augmente à chaque tour</li><li>Continuez à discuter jusqu&#39;à ce que vous remarquiez que les prompt tokens cessent de croître ou que les anciens messages disparaissent du contexte</li><li>Comptez combien de tours ont tenu avant que la fenêtre ne soit pleine</li><li>Changez maintenant la fenêtre de contexte à <strong>8 192 tokens</strong> dans les Chat Settings et répétez l&#39;expérience</li></ol><div class="tip custom-block"><p class="custom-block-title">Utilisez la commande slash /context</p><p>Vous pouvez rapidement changer la taille de la fenêtre de contexte en tapant <code>/context 2048</code> ou <code>/context 8192</code> dans la zone de saisie du chat, au lieu de naviguer vers les Chat Settings à chaque fois.</p></div><p><strong>Ce que vous allez découvrir :</strong></p><p>Avec 2 048 tokens, la conversation se remplit en environ 4-7 tours selon la longueur des messages. Avec 8 192, vous obtenez environ 4 fois plus de tours. La relation est approximativement linéaire — doubler le contexte, c&#39;est doubler la longueur de la conversation.</p><p>Observez attentivement le Metrics Dashboard : les prompt tokens croissent régulièrement, puis atteignent un plateau lorsque la fenêtre glissante entre en action. Ce plateau est le moment où les messages anciens commencent à disparaître.</p><p><strong>Notez vos observations :</strong></p><table tabindex="0"><thead><tr><th>Fenêtre de contexte</th><th>Tours avant saturation</th><th>Prompt tokens au plateau</th></tr></thead><tbody><tr><td>2 048</td><td>?</td><td>?</td></tr><tr><td>8 192</td><td>?</td><td>?</td></tr></tbody></table><hr><h3 id="exercice-2-le-test-d-amnesie" tabindex="-1">Exercice 2 : Le test d&#39;amnésie <a class="header-anchor" href="#exercice-2-le-test-d-amnesie" aria-label="Permalink to &quot;Exercice 2 : Le test d&#39;amnésie&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Réglez la fenêtre de contexte à <strong>2 048 tokens</strong> dans les <strong>Chat Settings</strong></li><li>Dans votre <strong>premier message</strong>, dites au modèle : <em>&quot;My name is Alex and my favorite color is blue. Please remember this.&quot;</em></li><li>Engagez une conversation sur des <strong>sujets sans rapport</strong> — posez des questions sur l&#39;histoire, la science, la cuisine, n&#39;importe quoi. Envoyez 5 à 10 messages.</li><li>Après plusieurs tours, demandez : <em>&quot;What is my name and what is my favorite color?&quot;</em></li><li>Le modèle se souvient-il ? Notez la réponse.</li><li>Réglez maintenant la fenêtre de contexte à <strong>8 192 tokens</strong> et répétez l&#39;expérience entière depuis l&#39;étape 2</li><li>À quel moment le modèle oublie-t-il avec la fenêtre plus grande ?</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Avec 2 048 tokens, le modèle oubliera probablement votre nom et votre couleur après seulement quelques tours de conversation sans rapport. Le message contenant vos informations personnelles a été poussé hors de la fenêtre glissante. Le modèle peut :</p><ul><li>Avouer son ignorance (&quot;I don&#39;t have that information&quot;)</li><li>Halluciner une réponse (affirmer avec assurance un nom incorrect)</li><li>Se souvenir partiellement (retrouver un fait correct et un autre faux)</li></ul><p>Avec 8 192 tokens, les faits survivent plus longtemps — mais ils finissent tout de même par disparaître si vous discutez assez longtemps. L&#39;oubli est <strong>inévitable</strong> ; seul le moment change.</p><p><strong>L&#39;observation critique :</strong> Le modèle ne sait pas qu&#39;il a oublié. Il ne dit jamais &quot;Je connaissais votre nom mais il a été retiré de mon contexte&quot;. Il se comporte comme si l&#39;information n&#39;avait jamais existé.</p><hr><h3 id="exercice-3-anatomie-du-budget-de-tokens" tabindex="-1">Exercice 3 : Anatomie du budget de tokens <a class="header-anchor" href="#exercice-3-anatomie-du-budget-de-tokens" aria-label="Permalink to &quot;Exercice 3 : Anatomie du budget de tokens&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Ayez une conversation d&#39;au moins 5 tours dans <strong>Chat Diagnostics</strong></li><li>Ouvrez le <strong>Prompt Inspector</strong> (vue d&#39;anatomie du prompt)</li><li>Examinez le <strong>diagramme en barres empilées</strong> montrant la répartition du budget de tokens : tokens du prompt système vs tokens de l&#39;historique de conversation vs tokens du message utilisateur</li><li>Notez la taille actuelle du prompt système</li><li>Allez maintenant dans <strong>Chat Settings</strong> et changez le prompt système pour quelque chose de <strong>très long</strong> — collez un paragraphe entier d&#39;instructions détaillées (par ex. <em>&quot;You are a helpful assistant who always responds in bullet points. You must cite sources for every claim. You should use formal academic English. You must never use contractions. Always begin your response with a summary sentence...&quot;</em> — faites-en 200+ mots)</li><li>Envoyez un nouveau message et réexaminez le Prompt Inspector</li><li>Comparez : combien d&#39;espace le prompt système étendu consomme-t-il ? Combien de tours de conversation en moins tiennent dans la fenêtre ?</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Le diagramme en barres empilées rend le compromis viscéralement clair. Un prompt système court (par ex. &quot;You are a helpful assistant&quot;) peut consommer 10-20 tokens. Un prompt système verbeux peut facilement en consommer 300-500 — soit 15-25 % d&#39;une fenêtre de contexte de 2 048 tokens, disparus avant même que la conversation ne commence.</p><p><strong>Questions de réflexion :</strong></p><ul><li>Si vous ne disposez que de 2 048 tokens au total, un prompt système de 500 tokens en vaut-il la peine ?</li><li>Comment réécririez-vous un long prompt système pour transmettre les mêmes instructions en moins de tokens ?</li><li>Que se passe-t-il avec le prompt système en cas de débordement du contexte — est-il jamais supprimé ?</li></ul><div class="warning custom-block"><p class="custom-block-title">Le prompt système est généralement protégé</p><p>La plupart des applications, y compris LLMxRay, protègent le prompt système de la troncature — il est toujours inclus. Cela signifie que le prompt système réduit de manière permanente l&#39;espace disponible pour l&#39;historique de conversation. Un prompt système surchargé est un impôt permanent sur chaque tour de la conversation.</p></div><hr><h3 id="exercice-4-comparaison-des-strategies-de-memoire" tabindex="-1">Exercice 4 : Comparaison des stratégies de mémoire <a class="header-anchor" href="#exercice-4-comparaison-des-strategies-de-memoire" aria-label="Permalink to &quot;Exercice 4 : Comparaison des stratégies de mémoire&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Démarrez une conversation fraîche dans <strong>Chat Diagnostics</strong> avec la fenêtre de contexte réglée à <strong>2 048 tokens</strong></li><li>Dans le premier message, communiquez au modèle trois faits spécifiques : votre nom, votre ville et votre métier</li><li>Ayez 8-10 tours de conversation sans rapport</li><li>Demandez au modèle de rappeler les trois faits. Notez ce dont il se souvient.</li><li>Activez maintenant <strong>Sliding Window</strong> (réglée à 20 messages) dans les <strong>Chat Settings</strong> et répétez l&#39;expérience</li><li>Ensuite, activez <strong>Auto-Summarization</strong> et répétez</li><li>Enfin, activez <strong>RAG Message Memory</strong> et répétez</li><li>Comparez les résultats entre toutes les stratégies</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><table tabindex="0"><thead><tr><th>Stratégie</th><th>Faits rappelés (sur 3)</th><th>Utilisation de tokens</th><th>Notes</th></tr></thead><tbody><tr><td>Aucune stratégie (brut)</td><td>?</td><td>Élevée (croissance illimitée)</td><td>Les messages les plus anciens sont simplement supprimés</td></tr><tr><td>Sliding Window (20)</td><td>?</td><td>Moyenne (plafonnée)</td><td>Messages récents conservés, anciens disparus</td></tr><tr><td>Auto-Summarization</td><td>?</td><td>Faible (compressée)</td><td>Le résumé peut ou non capturer vos faits</td></tr><tr><td>RAG Message Memory</td><td>?</td><td>Moyenne (sélective)</td><td>Récupère les messages passés pertinents à la demande</td></tr></tbody></table><p>La comparaison la plus révélatrice est entre Auto-Summarization et RAG Message Memory. Le résumé compresse tout en un court paragraphe, qui pourrait dire &quot;l&#39;utilisateur s&#39;est présenté&quot; sans préserver le nom réel. La récupération RAG peut retrouver le message original exact contenant vos faits — mais seulement si la requête de récupération déclenche une correspondance sémantique.</p><p><strong>Discussion :</strong></p><ul><li>Quelle stratégie préserve le plus de contexte tout en utilisant le moins de tokens ?</li><li>Existe-t-il une stratégie qui fonctionne bien pour tous les types de conversation, ou le meilleur choix dépend-il du cas d&#39;usage ?</li><li>Que se passerait-il si vous combiniez plusieurs stratégies ?</li></ul><hr><h2 id="points-cles" tabindex="-1">Points Clés <a class="header-anchor" href="#points-cles" aria-label="Permalink to &quot;Points Clés&quot;">​</a></h2><ol><li><strong>La fenêtre de contexte est un tampon de taille fixe</strong>, pas une mémoire persistante. Le modèle n&#39;a aucun état entre les appels — la conversation entière est renvoyée à chaque fois, et lorsqu&#39;elle dépasse la limite, les anciens messages sont silencieusement supprimés.</li><li><strong>Le prompt système, l&#39;historique de conversation et la réponse du modèle sont tous en concurrence</strong> pour le même budget de tokens. Chaque token dépensé pour un composant est indisponible pour les autres.</li><li><strong>Le débordement du contexte est une coupure nette</strong>, pas un effacement progressif. Le modèle n&#39;a aucune conscience que des messages ont été supprimés et ne peut pas distinguer une information &quot;oubliée&quot; d&#39;une information qui n&#39;a jamais été fournie.</li><li><strong>Les stratégies de mémoire sont des palliatifs avec perte</strong>, pas des solutions. Fenêtre glissante, résumé, faits utilisateur et récupération RAG préservent chacun différents aspects de la conversation à différents coûts, mais aucun ne remplace intégralement le contexte original.</li><li><strong>Des fenêtres de contexte plus grandes aident mais ne sont pas une panacée</strong>. Elles entraînent des coûts de calcul plus élevés, une latence accrue et le problème du &quot;perdu au milieu&quot; où les modèles sous-exploitent les informations enfouies dans de longs contextes.</li></ol><hr><h2 id="questions-de-discussion" tabindex="-1">Questions de Discussion <a class="header-anchor" href="#questions-de-discussion" aria-label="Permalink to &quot;Questions de Discussion&quot;">​</a></h2><ol><li>Pourquoi ne peut-on pas simplement rendre les fenêtres de contexte infinies ? Quelles sont les barrières computationnelles, architecturales et pratiques — et certaines d&#39;entre elles sont-elles susceptibles d&#39;être résolues prochainement ?</li><li>De nombreux assistants IA prétendent &quot;se souvenir&quot; de vous entre les conversations. Sachant ce que vous savez maintenant sur les fenêtres de contexte, que doit-il se passer en coulisses pour créer cette illusion ? Quelles sont les implications en matière de vie privée ?</li><li>Dans le Module 4, vous avez découvert le RAG — la récupération de documents pertinents pour augmenter l&#39;entrée du modèle. Comment la limite de la fenêtre de contexte affecte-t-elle la conception des systèmes RAG ? Que se passe-t-il lorsque les documents récupérés plus l&#39;historique de conversation dépassent la fenêtre de contexte ?</li><li>Si un modèle dispose d&#39;une fenêtre de contexte de 128K, cela signifie-t-il qu&#39;il peut exploiter de manière fiable une entrée de 128K tokens ? Que suggèrent les recherches sur le &quot;perdu au milieu&quot; concernant la longueur de contexte effective vs théorique ?</li><li>Imaginez que vous construisiez un chatbot de support client. Un client a une conversation de 50 messages couvrant plusieurs problèmes. Comment concevriez-vous la stratégie de mémoire pour garantir que le modèle n&#39;oublie jamais les détails du compte client tout en conservant de la place pour discuter du problème en cours ?</li></ol><hr><h2 id="lectures-complementaires" tabindex="-1">Lectures Complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to &quot;Lectures Complémentaires&quot;">​</a></h2><h3 id="articles-academiques" tabindex="-1">Articles académiques <a class="header-anchor" href="#articles-academiques" aria-label="Permalink to &quot;Articles académiques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Article</th><th>Auteurs</th><th>Année</th><th>Lien</th></tr></thead><tbody><tr><td>Attention Is All You Need</td><td>Vaswani, Shazeer, Parmar, Uszkoreit, Jones, Gomez, Kaiser, Polosukhin</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">arXiv:1706.03762</a></td></tr><tr><td>Lost in the Middle: How Language Models Use Long Contexts</td><td>Liu, Lin, Hewitt, Paranjape, Bevilacqua, Petroni, Liang</td><td>2023</td><td><a href="https://arxiv.org/abs/2307.03172" target="_blank" rel="noreferrer">arXiv:2307.03172</a></td></tr><tr><td>Extending Context Window of Large Language Models via Positional Interpolation</td><td>Chen, Wong, Chen, Tian</td><td>2023</td><td><a href="https://arxiv.org/abs/2306.15595" target="_blank" rel="noreferrer">arXiv:2306.15595</a></td></tr><tr><td>LongRoPE: Extending LLM Context Window Beyond 2 Million Tokens</td><td>Ding, Zhang, Zhang, Xu, Shang, Yang, Nishi, Zheng, Bian</td><td>2024</td><td><a href="https://arxiv.org/abs/2402.13753" target="_blank" rel="noreferrer">arXiv:2402.13753</a></td></tr><tr><td>Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks</td><td>Lewis, Perez, Piktus, Petroni, Karpukhin, Goyal, Kuttler, Lewis, Yih, Rocktaschel, Riedel, Kiela</td><td>2020</td><td><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noreferrer">arXiv:2005.11401</a></td></tr></tbody></table><h3 id="tutoriels-et-explications-visuelles" tabindex="-1">Tutoriels et explications visuelles <a class="header-anchor" href="#tutoriels-et-explications-visuelles" aria-label="Permalink to &quot;Tutoriels et explications visuelles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ressource</th><th>Auteur</th><th>Lien</th></tr></thead><tbody><tr><td>Attention? Attention!</td><td>Lilian Weng</td><td><a href="https://lilianweng.github.io/posts/2018-06-24-attention/" target="_blank" rel="noreferrer">lilianweng.github.io</a></td></tr><tr><td>The Illustrated Transformer</td><td>Jay Alammar</td><td><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">jalammar.github.io</a></td></tr></tbody></table><hr><h2 id="evaluation" tabindex="-1">Évaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Évaluation&quot;">​</a></h2><p><strong>Option A — Journal de la fenêtre de contexte (individuel, 1 page) :</strong> À l&#39;aide de Chat Diagnostics de LLMxRay, effectuez le test d&#39;amnésie (Exercice 2) avec trois tailles de fenêtre de contexte différentes (2 048 / 4 096 / 8 192). Pour chaque taille, notez le tour exact auquel le modèle oublie vos faits initiaux. Présentez vos résultats dans un tableau et expliquez la relation entre la taille du contexte et la mémoire conversationnelle. Incluez des captures d&#39;écran du Metrics Dashboard montrant la courbe de croissance des tokens.</p><p><strong>Option B — Évaluation des stratégies de mémoire (en binôme, 1 page) :</strong> Testez les quatre stratégies de mémoire (sliding window, auto-summarization, user facts, RAG message memory) en utilisant le même script de conversation de 15 tours. Pour chaque stratégie, évaluez : (1) combien de faits originaux ont été préservés, (2) l&#39;utilisation totale de tokens, et (3) la qualité des réponses. Présentez une matrice de comparaison et recommandez quelle stratégie est la mieux adaptée à trois cas d&#39;usage différents : support client, tutorat et écriture créative.</p><p><strong>Option C — Proposition de conception système (groupes de 2-3, présentation de 5 minutes) :</strong> Concevez une architecture de mémoire pour un assistant d&#39;étude IA qui aide les étudiants à préparer leurs examens sur plusieurs semaines de conversation. L&#39;assistant doit retenir les sujets faibles de l&#39;étudiant, suivre la progression et ne jamais oublier les faits clés — le tout en fonctionnant sur un modèle local avec une fenêtre de contexte de 4 096 tokens. Présentez votre architecture, justifiez chaque choix de stratégie de mémoire avec des preuves tirées de vos expériences LLMxRay, et démontrez les compromis en direct.</p><hr><h2 id="la-suite" tabindex="-1">La Suite <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La Suite&quot;">​</a></h2><p>Dans le <strong><a href="./module-6.html">Module 6 : L&#39;IA peut-elle utiliser des outils ?</a></strong>, vous explorerez l&#39;appel d&#39;outils (tool calling) — comment les modèles de langage peuvent aller au-delà de la génération de texte pour exécuter du code, effectuer des recherches sur le web, interroger des bases de données et interagir avec des systèmes externes. Vous découvrirez que l&#39;utilisation d&#39;outils transforme le modèle d&#39;un prédicteur de texte en un agent, et vous examinerez à la fois la puissance et les risques de donner à l&#39;IA l&#39;accès à des actions dans le monde réel.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 5 sur 8</strong> du Kit Enseignants LLMxRay <a href="./module-4.html">← Module 4 : Que voit le modèle ?</a> | <a href="./index.html">Retour au programme</a> | <a href="./module-6.html">Module 6 : L&#39;IA peut-elle utiliser des outils ? →</a></p></div>',103)])])}const q=t(l,[["render",u]]);export{v as __pageData,q as default};
